var LI=[];
function qLibro(){
  LI=[{n:'📄 Páginas iniciales',d:'Portada · Tabla de contenido · Presentación · Competencias',fn:'libro_inicio.md',t:'ini'}];
  D.mods.forEach(function(m,mi){
    LI.push({n:'📦 Módulo '+(mi+1)+': '+m.n,d:'Presentación del módulo',fn:'libro_mod'+(mi+1)+'.md',t:'mod',mi:mi});
    m.caps.forEach(function(cap,ci){var cn=mi*3+ci+1; LI.push({n:'📖 Cap '+cn+': '+cap,d:'Módulo '+(mi+1)+' — '+m.n,fn:'libro_cap'+cn+'.md',t:'cap',cn:cn,cap:cap,mi:mi});});
  });
  LI.push({n:'📋 Evaluación y Bibliografía',d:'Tabla evaluativa · Criterios · Recursos y fuentes',fn:'libro_biblio.md',t:'bib'});
  return LI.map(function(x){return {name:x.n,detail:x.d};});
}
async function genLibro(){
  if(!getApiKey()){alert('⚠️ Ingresa tu API key en el sidebar.');return;}
  var btn=document.querySelector('#br-libro button'); btn.disabled=true;
  var c=ctx(), s=sysL();
  for(var i=0;i<LI.length;i++){
    var item=LI[i]; qSt('libro',i,'gen');
    try{var r=await api(s,pLibro(item,c),4096); r=r.replace(/^\s*```markdown\s*/i,'').replace(/\s*```\s*$/,''); F[item.fn]=r; qSt('libro',i,'done'); qResult('libro',i,item.fn,r); updStats();}
    catch(e){qSt('libro',i,'err');}
  }
  btn.disabled=false;
}
function pLibro(item,c){
  var s=Math.random();
  if(item.t==='ini')return c+'\n\nGenera SOLO las siguientes secciones del Libro Guía (NO generes portada, NO generes tabla de contenido, eso ya lo tenemos):\n\n## Presentación del Libro Guía\n3 párrafos: bienvenida al curso, contexto del sector '+D.sector+' en '+D.pais+', qué encontrará el estudiante.\n\n## Información General del Curso\nTabla con: Nombre del curso, Unidad de competencia, Modalidad, Estructura (3 módulos · 9 capítulos · 80 horas), Año '+new Date().getFullYear()+'.\n\n## Competencias a Desarrollar\n6 competencias concretas como bullets, cada una iniciando con un verbo de acción (Diseñar, Aplicar, Utilizar, Analizar, Identificar, Estructurar).\n\nSemilla:'+s;
  if(item.t==='mod')return c+'\n\nGenera la PRESENTACIÓN DEL MÓDULO '+(item.mi+1)+' — "'+D.mods[item.mi].n+'":\n- Descripción motivadora (2 párrafos, enfoque en '+D.sector+' en '+D.pais+', tuteando al estudiante)\n- Tabla: Capítulo | Tema central | Horas aprox (8h cada uno)\nTotal del módulo: 24 horas.\nSemilla:'+s;
  if(item.t==='cap')return c+'\n\nGenera el CAPÍTULO '+item.cn+' COMPLETO: "'+item.cap+'"\nMódulo '+(item.mi+1)+': '+D.mods[item.mi].n+'\n\nIncluye:\n1. Secciones '+item.cn+'.1 a '+item.cn+'.5 — 250-400 palabras c/u, ejemplos reales de '+D.sector+' en '+D.pais+', datos numéricos verificables\n2. Mínimo 1 tabla comparativa con datos del sector\n3. ■ Caso '+D.pais+': empresa real del sector aplicando el tema (en cursiva, con datos numéricos)\n4. ✏ Actividad de Apoyo '+item.cn+'.1: ejercicio concreto con pasos numerados\n   ■■ Nota: actividad de apoyo, opcional, no subir a Moodle.\n5. ✏ Actividad de Apoyo '+item.cn+'.2: segundo ejercicio práctico con pasos numerados\n   ■■ Nota: actividad de apoyo, opcional, no subir a Moodle.\n6. ■ Glosario del Capítulo: 8-12 términos con definición clara de 1-2 líneas cada uno\n\nNO generes portada ni tabla de contenido. Empieza directamente con # Capítulo...\nSemilla:'+s;
  if(item.t==='bib')return c+'\n\nGenera la sección de EVALUACIÓN Y BIBLIOGRAFÍA:\n- Tabla evaluativa: foros 15% / quices 20% / talleres 25% / proyecto 30% / autoevaluación 10%\n- Criterios: 3.0/5.0, 80% actividades, proyecto mín 3.0\n- 6 libros reales sobre '+D.sector+'\n- Normativa legal aplicable en '+D.pais+' al sector '+D.sector+'\n- 6 plataformas de formación gratuita del sector\n- 5 recursos digitales útiles\nSemilla:'+s;
  return c+'\n\nGenera: '+item.n+'\nSemilla:'+s;
}

