var PI=[];
function qPaginas(){
  PI=[
    {n:'🏠 Bienvenida',d:'seccion0_bienvenida.html',fn:'seccion0_bienvenida.html',t:'bv'},
    {n:'🎵 Audio bienvenida',d:'seccion0_audio_bienvenida.html',fn:'seccion0_audio_bienvenida.html',t:'au'},
    {n:'📋 Introducción completa',d:'seccion0_introduccion_completa.html',fn:'seccion0_introduccion_completa.html',t:'ic'},
    {n:'🗺️ Ruta de aprendizaje',d:'seccion1_ruta_aprendizaje.html',fn:'seccion1_ruta_aprendizaje.html',t:'ru'},
    {n:'📚 Libro guía (página)',d:'seccion1_libro_guia.html',fn:'seccion1_libro_guia.html',t:'lb'},
    {n:'📻 Audiolibro (placeholder)',d:'seccion1_audiolibro.html',fn:'seccion1_audiolibro.html',t:'alp'}
  ];
  D.caps.forEach(function(cap){
    PI.push({n:'▶ Video Cap '+cap.n+': '+cap.t.substring(0,25)+'…',d:'cap'+cap.n+'_video_interactivo.html',fn:'cap'+cap.n+'_video_interactivo.html',t:'vi',cap:cap});
    PI.push({n:'🎮 Desc SCORM Cap '+cap.n,d:'cap'+cap.n+'_descripcion_actividad.html',fn:'cap'+cap.n+'_descripcion_actividad.html',t:'sc',cap:cap});
  });
  D.mods.forEach(function(m,mi){PI.push({n:'📝 Examen Unidad '+(mi+1),d:'examen_unidad'+(mi+1)+'_descripcion.html',fn:'examen_unidad'+(mi+1)+'_descripcion.html',t:'ex',mi:mi,m:m});});
  PI.push({n:'🏆 Cierre del curso',d:'examen_final_descripcion.html',fn:'examen_final_descripcion.html',t:'ci'});
  // Compatibilidad con cursos anteriores que usaban in/me separados (no se muestran en UI)
  PI.push({n:'Introducción al curso',d:'seccion0_introduccion.html',fn:'seccion0_introduccion.html',t:'in',legacy:true});
  PI.push({n:'Metodología',d:'seccion0_metodologia.html',fn:'seccion0_metodologia.html',t:'me',legacy:true});
  return PI.filter(function(x){return !x.legacy;}).map(function(x){return {name:x.n,detail:x.d};});
}
/* ── TAREA 3/4: Sanitizador defensivo de iframes de video falsos ──────────────
   Elimina cualquier iframe que apunte a mod/hvp, YouTube, youtu.be o Vimeo
   en páginas de video (tipo 'vi') cuando NO hay video real validado en MEDIA.
   Si el item no es 'vi' o hay un video real, devuelve el HTML sin tocar.
   Reemplaza el iframe por un bloque visual "Video pendiente". ─────────────── */
function sanitizeVideoIframes(html,item){
  if(!html)return html;
  /* Solo actuar en páginas de tipo 'vi' (cap{N}_video_interactivo.html) */
  if(!item||item.t!=='vi')return html;
  /* Si hay video real validado en MEDIA, no tocar */
  var capN=item.cap&&item.cap.n;
  var hasRealVideo=capN&&MEDIA&&MEDIA.videos&&MEDIA.videos['v'+capN]&&String(MEDIA.videos['v'+capN]).length>4;
  if(hasRealVideo)return html;
  /* Patrones de iframe falso a eliminar */
  var fakePatterns=[
    /(<iframe[^>]*(?:mod\/hvp\/embed\.php|youtube\.com|youtu\.be|vimeo\.com)[^>]*>[\s\S]*?<\/iframe>)/gi,
    /(<iframe[^>]*(?:mod\/hvp\/embed\.php|youtube\.com|youtu\.be|vimeo\.com)[^>]*\/>)/gi
  ];
  var PENDING_BLOCK='<div style="position:relative;padding-bottom:56.25%;height:0;overflow:hidden;border-radius:12px;margin-bottom:20px;">'
    +'<div style="position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;background:rgba(255,255,255,0.03);border:2px dashed rgba(255,255,255,0.12);border-radius:12px;gap:12px;">'
    +'<div style="width:64px;height:64px;border-radius:50%;background:rgba(255,255,255,0.07);display:flex;align-items:center;justify-content:center;font-size:26px;">&#9654;</div>'
    +'<p style="font-size:15px;font-weight:700;color:#E2E6F3;margin:0;">Video en preparación</p>'
    +'<p style="font-size:12px;color:rgba(226,230,243,0.45);margin:0;text-align:center;max-width:260px;">El video interactivo de este capítulo estará disponible próximamente</p>'
    +'</div></div>';
  var sanitized=html;
  fakePatterns.forEach(function(re){sanitized=sanitized.replace(re,PENDING_BLOCK);});
  /* También limpiar ratio-containers que envuelven un iframe falso y quedaron vacíos */
  sanitized=sanitized.replace(/<div[^>]*padding-bottom:[^>]*>\s*<\/div>/gi,'');
  return sanitized;
}
